((SELECT id FROM chapters WHERE code = 'CH_3' AND textbook_id = (SELECT id FROM textbooks WHERE code = 'HOA_10')), 'BAI_14', 'ÔN TẬP CHƯƠNG 3', 68, 14, $JSON$
{
