INSERT INTO lessons (chapter_id, code, name, page, sort_order, knowledge_json) VALUES
((SELECT id FROM chapters WHERE code = 'CH_5' AND textbook_id = (SELECT id FROM textbooks WHERE code = 'HOA_10')), 'BAI_18', 'ÔN TẬP CHƯƠNG 5', 89, 18, $JSON$
{
  "content": [
    "BÀI 18 ÔN TẬP CHƯƠNG 5",
    "",
    "I HỆ THỐNG HOÁ KIẾN THỨC",
    "Hoàn thành các nội dung còn thiếu sau đây:",
    "Chất phản ứng $\\longrightarrow$ Sản phẩm, $\\Delta_{\\text{r}}\\text{H}$ > 0 (phản ứng ...?... nhiệt)",
