INSERT INTO lessons (chapter_id, code, name, page, sort_order, knowledge_json) VALUES
((SELECT id FROM chapters WHERE code = 'CH_6' AND textbook_id = (SELECT id FROM textbooks WHERE code = 'HOA_10')), 'BAI_20', 'ÔN TẬP CHƯƠNG 6', 101, 20, $JSON$
{
  "content": [
    "BÀI 20 ÔN TẬP CHƯƠNG 6",
    "",
    "I HỆ THỐNG HOÁ KIẾN THỨC",
    "Hoàn thành các nội dung còn thiếu sau đây:",
    "Tốc độ phản ứng:",
    "Xét phản ứng hoá học dạng tổng quát: aA + bB $\\longrightarrow$ cC + dD.",
    "Biểu thức tốc độ trung bình của phản ứng: v$_\\text{tb}$ = ...?...",
    "Nếu phản ứng trên là một phản ứng đơn giản thì biểu thức tốc độ phản ứng theo hằng số tốc độ phản ứng: v = ...?...",
    "",
