INSERT INTO lessons (chapter_id, code, name, page, sort_order, knowledge_json) VALUES
((SELECT id FROM chapters WHERE code = 'CH_8' AND textbook_id = (SELECT id FROM textbooks WHERE code = 'HOA_10')), 'CUOISACH', 'THÔNG TIN CUỐI SÁCH', 121, 25, $JSON$
{
  "content": [
    "[Logo: HUÂN CHƯƠNG HỒ CHÍ MINH]",
    "",
