INSERT INTO lessons (chapter_id, code, name, page, sort_order, knowledge_json) VALUES
((SELECT id FROM chapters WHERE code = 'C6' AND textbook_id = (SELECT id FROM textbooks WHERE code = 'HOA_12')), 'B19', 'Tính chất vật lí và tính chất hoá học của kim loại', 91, 2, $JSON$
{
  "content": [
    "# BÀI 19 TÍNH CHẤT VẬT LÍ VÀ TÍNH CHẤT HOÁ HỌC CỦA KIM LOẠI",
