INSERT INTO lessons (chapter_id, code, name, page, sort_order, knowledge_json) VALUES
((SELECT id FROM chapters WHERE code = 'CH2' AND textbook_id = (SELECT id FROM textbooks WHERE code = 'LI10')), 'B7', 'Bài 7. Đồ thị độ dịch chuyển - thời gian', 35, 4, $JSON$
{
  "content": [
    "# Bi 7  TH  DCH CHUYN  THI GIAN",
    "",
    "**Khi ng:**",
