INSERT INTO lessons (chapter_id, code, name, page, sort_order, knowledge_json) VALUES
((SELECT id FROM chapters WHERE code = 'CH0' AND textbook_id = (SELECT id FROM textbooks WHERE code = 'LI11')), 'B0', 'Chương mở đầu', 1, 1, $JSON$
{
  "content": [
    "VŨ VĂN HÙNG (Tổng Chủ biên)",
